function biplotOption(r, F) {
  const U = toRows(r.U); const V = toRows(r.V);
  // S 是**列数**（U 是 p x S、V 是 q x S），不是行数。
  // 上一版按 U.length 判，秩 1 时 p 行照样 >=2 -> 硬画出一张只有一维的"双标图"。
