const { gmr4SheetSpec: spec, sheetIo } = await loadFrontendUtils(['gmr4SheetSpec', 'sheetIo']);
const TMP = fs.mkdtempSync(path.join(os.tmpdir(), 'cmp-'));
const id = process.argv[2] || 'rank1';
const sheets = spec.gmr4TemplateSheets(id);

// A) 不经 xlsx：直接 aoa -> mapWorkbook -> patch（test_gmr4_spec 的路子）
const asSheets = Object.fromEntries(sheets.map((s) => [s.name, s.aoa]));
const A = sheetIo.mapWorkbook(asSheets, spec.GMR4_IMPORT_SHEETS, { primary: 'X' });
const pa = spec.gmr4ToFormPatch(A.fields);
const payA = { X: JSON.parse(pa.xStr), Y: JSON.parse(pa.yStr), kfold: pa.kfold, seed: pa.seed };
if (pa.lambdas) payA.lambdas = pa.lambdas;

// B) 经真 xlsx 字节（readWorkbook 的等价复刻：sandbox 里 import('xlsx') 解析不到）
