const rd = XLSX.read(buf, { type: 'array' });
const read = {};
for (const nm of rd.SheetNames) {
  read[nm] = XLSX.utils.sheet_to_json(rd.Sheets[nm], { header: 1, blankrows: false, defval: '' });
}
const B = sheetIo.mapWorkbook(read, spec.GMR4_IMPORT_SHEETS, { primary: 'X' });
const pb = spec.gmr4ToFormPatch(B.fields);
const payB = { X: JSON.parse(pb.xStr), Y: JSON.parse(pb.yStr), kfold: pb.kfold, seed: pb.seed };
if (pb.lambdas) payB.lambdas = pb.lambdas;

console.log(id, 'payload A==B ?', JSON.stringify(payA) === JSON.stringify(payB));
console.log('  X[0] A', JSON.stringify(payA.X[0]));
console.log('  X[0] B', JSON.stringify(payB.X[0]));
console.log('  lambdas', JSON.stringify(payB.lambdas), 'kfold', payB.kfold, 'seed', payB.seed);

for (const [nm, p] of [['A', payA], ['B', payB]]) {
  const f = path.join(TMP, `${nm}.json`);
