  } catch (e) { code = e.status || 1; }
  if (code !== 0) { console.log(nm, 'exit', code, fs.readFileSync(f + '.err', 'utf8').slice(0, 300)); continue; }
  const r = JSON.parse(fs.readFileSync(f + '.out', 'utf8'));
  console.log(' ', nm, 'exit', code, 'S=', r.rank_selected, 'lam=', r.lambda_selected,
    'R2=', r.R2, 'R2part=', r.R2_partialled, 'rank_grid=', JSON.stringify(r.rank_grid),
