    tplShapeLine() {
      const t = this.tpl;
      if (!t) return '';
      const s = t.spec;
      const cov = s.expect && s.expect.covariates ? `，含 ${s.expect.covariates} 个协变量` : '，不含协变量';
      return `${s.n} 样本 × ${s.p} 预测变量 × ${s.q} 响应（真实秩 ${s.S}${cov}）`;
