      const t = this.tpl;
      if (!t) return '';
      const e = t.spec.expect || {};
      const parts = [];
      if (e.rank_selected != null) parts.push(`选型回到 S=${e.rank_selected}`);
      else parts.push('这个设计里选型本身不具信息，故意不给“期望秩”');
