.ra-shell > .main-content {
  /* box-sizing 不可省：全仓没有 global reset，默认 content-box。
     content-box 下 max-width:1200 说的是**内容宽**，而页头卡片自带
     padding: 28px 36px + border: 2px（摆两边共 76），于是页头实际宽 1276，
