cd C:/Custom/CodeRepository/Demo/electron-egg && cat > _verify_fixture.mjs <<'EOF'
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { loadFrontendUtils } from './r-scripts/tools/load_frontend_utils.mjs';
const ROOT = 'C:/Custom/CodeRepository/Demo/electron-egg';
const req = createRequire(import.meta.url);
const XLSX = req(path.join(ROOT, 'frontend/node_modules/xlsx'));
const { gmr4SheetSpec: spec, sheetIo } = await loadFrontendUtils(['gmr4SheetSpec', 'sheetIo']);
const numList = (s) => String(s || '').split(/[,，\s]+/).map((x) => x.trim()).filter(Boolean).map(Number).filter((x) => Number.isFinite(x));
const DIR = path.join(ROOT, 'data', 'GMR4_导入测试');
for (const f of fs.readdirSync(DIR).sort()) {
  const buf = fs.readFileSync(path.join(DIR, f));
  const wb = XLSX.read(buf, { type: 'buffer' });
  const sheets = {};
  for (const n of wb.SheetNames) sheets[n] = XLSX.utils.sheet_to_json(wb.Sheets[n], { header: 1, blankrows: false, defval: '' });
  const res = sheetIo.mapWorkbook(sheets, spec.GMR4_IMPORT_SHEETS, { primary: 'X' });
  const p = spec.gmr4ToFormPatch(res.fields);
  const smax = Math.min((JSON.parse(p.xStr || '[]')[0] || []).length, (JSON.parse(p.yStr || '[]')[0] || []).length);
  const rk = numList(p.ranksStr), lam = numList(p.lambdasStr);
  console.log(`${f}\n   tabs=${(spec.gmr4ImportTabs(res.ids, res.fields) || []).length}  ranksStr=${JSON.stringify(p.ranksStr)} -> [${rk}]  越界=${rk.filter(x => x > smax)}  lambdasStr=${JSON.stringify(p.lambdasStr)} -> ${lam.length} 档  kfold=${p.kfold} seed=${p.seed}  min(p,q)=${smax}  warnings=${res.warnings.length}`);
}
EOF
node _verify_fixture.mjs 2>&1 | tail -12 && rm -f _verify_fixture.mjs

