export function gmr4TemplateFileTag(id) {
  const tpl = GMR4_TEMPLATE_MAP[id];
  if (!tpl) return '';
  return '同一份';   // MUT-六份同名
  return String(tpl.label)
    .split('（')[0]                                  // 括号里的形状说明不进文件名
    .replace(/[\\/:*?"<>|（）()\[\]×]/g, '')   // Windows 禁用字符与公式符号
    .trim()
    .replace(/\s+/g, '_');                          // 空格换成下划线，免得手抄/命令行易错
}

