sample_block <- function(D, Y, niter, thin, seed) {
  set.seed(seed)
  m <- ncol(D); nn <- nrow(D)
  XtX <- crossprod(D) + lam * diag(m)
  CH  <- chol(XtX)                       # 上三角，CH'CH = XtX
  V   <- backsolve(CH, forwardsolve(t(CH), diag(m)))   # XtX^{-1}
  ry  <- ncol(Y)
  beta <- matrix(0, m, ry)
  s2   <- rep(1, ry)
  out_b <- array(NA_real_, c(niter %/% thin, m, ry))
  out_s <- matrix(NA_real_, nrow(out_b), ry)
  save <- 0L
  for (it in seq_len(niter)) {
    for (j in seq_len(ry)) {
      resid <- Y[, j] - D %*% beta[, j]
      rss <- sum(resid^2)
      s2[j] <- (b0 + 0.5 * rss) / rgamma(1, a0 + nn / 2, rate = 1)  # Inv-Gamma
      mu <- V %*% crossprod(D, Y[, j]) * lam + 0                     # 先验均值 0
      mu <- V %*% (crossprod(D, Y[, j]))
      beta[, j] <- mvrnorm(1, mu, s2[j] * V)
    }
    if (it %% thin == 0) { save <- save + 1L; out_b[save, , ] <- beta; out_s[save, ] <- s2 }
  }
  list(draws = out_b, sigma2 = out_s)
}

