rhat_of <- function(pieces) {
  nn <- nrow(pieces[[1]])
  sapply(seq_len(p * q), function(j) {
    H <- do.call(cbind, lapply(pieces, function(m) m[, j, drop = FALSE]))
    W <- mean(apply(H, 2, var))
    # B 用的是**列均值**（每条“半链”自己的均值）的方差。写成 rowMeans 是把
    # 8 条序列按行平均（方差≈W/8），得到 B=nn*W/8 → R̂≈sqrt(1.12)≈1.058：
    # 一个常数偏高，而且对链间差异完全不敏感 —— spike 里那个“1.06 不随迭代下降”就是它。
    B <- nn * var(colMeans(H))
    sqrt((((nn - 1) / nn) * W + B / nn) / W)
  })
}

