 */
async checkRAvailable() {
  return new Promise((resolve) => {
    const test = (0, import_child_process.spawn)(this.rPath, ["--version"]);
    test.on("error", (err) => {
      import_log2.logger.error("[RService] R not found:", err.message);
      resolve(false);
    });
    test.on("close", (code) => {
      const available = code === 0;
      import_log2.logger.info("[RService] R availability check:", available ? "available" : "not available");
      resolve(available);
    });
  });
}
