zcols <- function(M, tag, dropped) {
  sds <- apply(M, 2, stats::sd)
  keep <- which(is.finite(sds) & sds > 1e-12)
  if (length(keep) < ncol(M)) {
    dropped <<- c(dropped, sprintf("%s 里有常量列（第 %s 列，方差为 0），已自动剔除；常量列不可能解释任何变异。",
                                   tag, paste(setdiff(seq_len(ncol(M)), keep), collapse = ",")))
  }
  if (!length(keep)) stop(sprintf("%s 全是常量列，无法分析。", tag))
  list(Z = scale(M[, keep, drop = FALSE], center = TRUE, scale = sds[keep]),
       keep = keep, center = unname(colMeans(M[, keep, drop = FALSE])), scale = unname(sds[keep]))
}

