  else if (k == 1L) om <- matrix(om, nrow = 1, ncol = q)
  INDa[ci, s, , ] <- g %*% om
  dd <- Bd[s, 1:p, , drop = TRUE]
  if (q == 1L) dd <- matrix(dd, nrow = p, ncol = 1)
  DIRa[ci, s, , ] <- dd
