export const ERA_FORM_FIELDS = ['xStr', 'mStr', 'yStr', 'chains', 'iterations', 'thin',
  'seed', 'priorLambda', 'prob'];

/** 预览 tab 顺序（外壳只按这个数组摆） */
export const ERA_PREVIEW_TABS = [
  { key: 'X', labelOf: (p) => `预测变量 X（${p.rows} 样本 × ${p.cols} 列）` },
  { key: 'M', labelOf: (p) => `中介变量 M（${p.rows} 样本 × ${p.cols} 列）` },
