  {
    key: 'excel',
    label: '分析结果（Excel：结论 / 效应表 / 方差分解 / 收敛诊断 / 模型信息）',
    type: 'xlsx',
    fileTag: '结果',
    sheets(ctx) {
      const { r, templateLabel, diagnostics } = ctx;
      const lab = r.cell_labels || [];
