import fs from 'node:fs';
import { execFileSync } from 'node:child_process';
import { loadFrontendUtils } from './load_frontend_utils.mjs';

const { gmr4SheetSpec: g, gmr4Charts: c } = await loadFrontendUtils(['gmr4SheetSpec', 'gmr4Charts']);
const R = 'r-portable/bin/Rscript.exe';

for (const id of ['singleResp', 'kfold2', 'ranksGrid']) {
  const sh = g.gmr4TemplateSheets(id);
  const kv = Object.fromEntries(sh[sh.length - 1].aoa.slice(1));
  const col = (t) => t.aoa.slice(1).map((r) => r.slice(1).map(Number));
  const pl = { X: col(sh[0]), Y: col(sh[1]), kfold: +kv.kfold, seed: +kv.seed };
  if (kv.ranks) pl.ranks = String(kv.ranks);
  if (kv.lambdas) pl.lambdas = String(kv.lambdas);
  // 有协变量表时（第 3 张）一起喂进去
  if (sh.length >= 4 && sh[2].name === '协变量Z') pl.Z = col(sh[2]);
  const f = `.tmp_probe_${id}.json`;
  fs.writeFileSync(f, JSON.stringify(pl));
  let r = null;
  try {
    execFileSync(R, ['r-scripts/gmr4.R', f, f + '.out', f + '.err'], { stdio: 'pipe' });
    r = JSON.parse(fs.readFileSync(f + '.out', 'utf8'));
  } catch (e) {
    console.log(id, '引擎拒绝:', fs.readFileSync(f + '.err', 'utf8').slice(0, 140));
  }
  if (r) {
    console.log('====', id, '====');
    console.log('  rank_selected=', r.rank_selected, '| rank_grid=', JSON.stringify(r.rank_grid),
      '| lambda_grid=', JSON.stringify(r.lambda_grid));
    console.log('  R2偏后=', r.R2_partialled, '| covariates=', r.covariates_partialled_out,
      '| 诊断=', JSON.stringify(r.diagnostics || []));
    const fmt = (v) => (v && v.toFixed ? v.toFixed(3) : String(v));
    for (const k of ['selection', 'biplot', 'cvHeat', 'r2']) {
      let o = null, err = '';
      try { o = c.GMR4_CHART_BUILDERS[k](r, fmt); } catch (e) { err = String(e.message).slice(0, 50); }
      console.log(`   ${k:}`.padEnd(12), o === null ? 'null' : (o.series ? `series ${o.series.length}` : `无 series! keys=${Object.keys(o)}`), err);
    }
  }
  fs.unlinkSync(f);
  for (const x of [f + '.out', f + '.err']) if (fs.existsSync(x)) fs.unlinkSync(x);
}

