const R = 'r-portable/bin/Rscript.exe';

const lcgr = (seed) => { let s = seed >>> 0; return () => ((s = (1103515245 * s + 12345) & 0x7fffffff) / 0x80000000); };
const rr = (r) => { const u = Math.max(r(), 1e-9), v = r(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };

/** 直接构造 X/M/Y：可指定两条中介通路的符号 */
function build({ n = 60, p = 2, k = 2, q = 2, gamma, omegaDir, cancel = false, seed = 7 }) {
  const r = lcgr(seed);
  const X = []; const M = []; const Y = [];
  for (let i = 0; i < n; i++) {
    const x = Array.from({ length: p }, () => rr(r));
    const m = Array.from({ length: k }, () => 0);
    for (let a = 0; a < p; a++) for (let kk = 0; kk < k; kk++) m[kk] += x[a] * gamma[a][kk];
    m.forEach((v, kk) => { m[kk] = v + (cancel ? 0 : 0.9) * rr(r); });
    const y = Array.from({ length: q }, () => 0);
    for (let kk = 0; kk < k; kk++) for (let j = 0; j < q; j++) y[j] += m[kk] * omegaDir[kk][j];
    const row = y.map((v, j) => v + (cancel ? 0 : 0.5 * x[j % p]) + 0.7 * rr(r));
    X.push(x); M.push(m); Y.push(row);
  }
  return { X, M, Y };
}

async function run(tag, payload) {
  const f = `r-scripts/tools/.tmp_bm_${tag}.json`;
  fs.writeFileSync(f, JSON.stringify(payload));
  let r = null, code = 0;
  try { execFileSync(R, ['r-scripts/bayesian_era_mediation.R', f, f + '.out', f + '.err'], { stdio: 'pipe' }); r = JSON.parse(fs.readFileSync(f + '.out', 'utf8')); }
  catch (_) { code = 1; }
  if (code) { console.log(tag, '拒绝:', fs.readFileSync(f + '.err', 'utf8').slice(0, 120)); }
  else {
    const bm = r.indirect_by_mediator;
    console.log(`\n==== ${tag} ====  K=${bm.mediator_labels.length} cells=${bm.cells.length} 抵消=${bm.cancelled_count}`);
    bm.per_mediator.forEach((blk, kk) => console.log(`  M${kk + 1} 间接均值 [${blk.mean.map((v) => v.toFixed(3)).join(', ')}]`));
    console.log(`  合计   [${r.effects.indirect.mean.map((v) => v.toFixed(3)).join(', ')}]`);
    console.log('  被抵消的格子:', JSON.stringify(bm.cancelled_cells));
    const dg = (r.diagnostics || []).filter((d) => /抵消|内部校验/.test(d));
    dg.forEach((d) => console.log('  诊断:', d.slice(0, 130)));
  }
  fs.unlinkSync(f); for (const x of [f + '.out', f + '.err']) if (fs.existsSync(x)) fs.unlinkSync(x);
}

// 1) 现有模板 k=1（partmed）：结构必须存在且只有一条通路，不许有抵消
const sh = e.eraTemplateSheets('partmed');
const col = (t) => t.aoa.slice(1).map((r) => r.slice(1).map(Number));
const kv = Object.fromEntries(sh[3].aoa.slice(1));
run('k1partmed', { X: col(sh[0]), M: col(sh[1]), Y: col(sh[2]), chains: +kv.chains, iterations: +kv.iterations, thin: +kv.thin, seed: +kv.seed, prior_lambda: +kv.prior_lambda, prob: +kv.prob });

// 2) 故意抵消：γ 相同，两条中介的 ω 反号，噪声压到很小
run('cancel', { ...build({ cancel: true, gamma: [[1.2, 0.9], [0.8, 1.1]], omegaDir: [[1.0, -0.9], [-1.0, 0.9]] }), chains: 2, iterations: 1500, thin: 4, seed: 9 });

// 3) 同向不抵消（对照组，不该报抵消）
run('sameSign', { ...build({ cancel: false, gamma: [[1.2, 0.9], [0.8, 1.1]], omegaDir: [[1.0, 0.9], [1.0, 0.9]] }), chains: 2, iterations: 1500, thin: 4, seed: 9 });

// 4) highdim 模板（k=3）跑通且结构齐
const sh4 = e.eraTemplateSheets('highdim');
const kv4 = Object.fromEntries(sh4[3].aoa.slice(1));
const p4 = { X: col(sh4[0]), M: col(sh4[1]), Y: col(sh4[2]), chains: 2, iterations: 800, thin: 10, seed: +kv4.seed, prior_lambda: 1, prob: 0.95 };
run('highdim_small', p4);

