# 抵消识别：同一格子里必须有方向相反且**都不微弱**的两条通路，而合计又明显小于最大单条。
// 量级下限不能只拿比例：highdim（随机 ω 的高维设计）实测会报 5/24 个“抵消”，
// 而那些通路只有 ±0.1 —— 随机符号互相碰了一下，拿它吓用户是误报。
// 所以同时要求：两侧绝对值都 >= 0.15（标准化尺度上算得是一条真通路），
// 小的一侧 >= 最大一侧的 30%，合计 <= 最大一侧的 40%。
cancel_idx <- integer(0)
if (k >= 2L) {
  stack <- simplify2array(lapply(path_pm, function(m) as.vector(m)))   # p*q x k（k=2 时也是矩阵）
  if (!is.matrix(stack)) stack <- matrix(as.vector(stack), ncol = k)
  for (e in seq_len(p * q)) {
    v <- stack[e, ]
    pos <- v[v > 0.15]; neg <- v[v < -0.15]
    if (length(pos) && length(neg)) {
      strongest <- max(abs(v))
      smallest_side <- min(min(abs(pos)), max(abs(neg)))
      if (smallest_side >= 0.3 * strongest && abs(sum(v)) <= 0.4 * strongest) cancel_idx <- c(cancel_idx, e)
    }
  }
}

