/**
 * 分中介通路的表行（导出与界面共用一份）。
 * 为什么值得单独一张：引擎每个格子报的"间接效应"是所有中介的合计，
 * 两条方向相反的强通路会在合计里互相抹平 —— 只看合计会把"有两条强通路"
 * 错读成"没有中介"。cancelmed 模板实测 4/4 格被判抵消。
 */
export function eraMediatorPathRows(r) {
  const bm = r.indirect_by_mediator;
  const head = ['格子', '中介', '通路·均值', '通路·下界', '通路·上界', '通路>0 概率', 'OLS 通路', '本格合计间接', '参与抵消'];
  if (!bm || !bm.per_mediator || !bm.per_mediator.length) return [head];
  const lab = r.cell_labels || [];
  const cancelled = new Set(bm.cancelled_cells || []);
  const rows = [];
  lab.forEach((nm, ci) => {
    bm.per_mediator.forEach((blk, mi) => {
      const m = blk.mean[ci];
      rows.push([nm, bm.mediator_labels[mi], m, blk.hdi_lo[ci], blk.hdi_hi[ci],
        blk.prob_gt0[ci], blk.ols[ci], r.effects.indirect.mean[ci],
        cancelled.has(nm) && Math.abs(m) >= 0.15 ? '是' : '']);
    });
  });
  return [head].concat(rows);
}
