import fs from 'node:fs';
import { execFileSync } from 'node:child_process';

const R = 'r-portable/bin/Rscript.exe';
const ENG = 'r-scripts/bayesian_era_mediation.R';
const rr = (a) => { let s = a >>> 0; return () => ((s = (1103515245 * s + 12345) & 0x7fffffff) / 0x80000000); };
const rn = (g) => { const u = Math.max(g(), 1e-9), v = g(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
const mat = (n, k, g) => Array.from({ length: n }, () => Array.from({ length: k }, () => Number(rn(g).toFixed(4))));

async function go(tag, n, p, k, q, mode) {
  const g = rn.bind(null, rr(1234));
  const r = rr(1234);
  const norm = () => { const u = Math.max(r(), 1e-9), v = r(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
  const X = mat(n, p, norm);
  // mode=orth: M 与 X 独立；mode:comp: Y 需要 X 与 M 一起才预测得好（联合强于各自之和）
  const M = mat(n, k, norm);
  const Y = [];
  for (let i = 0; i < n; i++) {
    const row = [];
    for (let j = 0; j < q; j++) {
      let a = 0;
      for (let t = 0; t < p; t++) a += X[i][t] * (0.55 - 0.1 * t);
      for (let t = 0; t < k; t++) a += M[i][t] * (0.55 - 0.12 * t);
      // 互补设计：再加一项 X 与 M 的"共同驱动"，它单独进任一侧都不显著
      if (mode === 'comp') a += 0.9 * (X[i][0] + M[i][0]) / 2 * 0.6;
      row.push(Number((a + norm() * 0.85).toFixed(4)));
    }
    Y.push(row);
  }
  const f = `r-scripts/tools/.tmp_np_${tag}.json`;
  fs.writeFileSync(f, JSON.stringify({ X, M, Y, chains: 2, iterations: 2000, thin: 4, seed: 7, prior_lambda: 1, prob: 0.95 }));
  try { execFileSync(R, [ENG, f, f + '.out', f + '.err'], { stdio: 'pipe' }); }
  catch (e) { console.log(tag, '拒绝:', fs.readFileSync(f + '.err', 'utf8').slice(0, 90)); return; }
  const o = JSON.parse(fs.readFileSync(f + '.out', 'utf8'));
  const vp = o.variance_partition;
  const names = ['x_unique', 'shared', 'm_unique', 'residual'];
  names.forEach((nm) => {
    const v = Array.isArray(vp[nm]) ? vp[nm] : [vp[nm]];
    console.log(`  ${tag} ${nm.padEnd(10)} ${v.map((x) => (typeof x === 'number' ? x.toFixed(4) : x)).join('  ')}`);
  });
  const all = names.flatMap((nm) => (Array.isArray(vp[nm]) ? vp[nm] : [vp[nm]])).filter((x) => typeof x === 'number');
  console.log(`  → ${tag}: 出现负分量 ${all.some((x) => x < -1e-6)}（最负 ${Math.min(...all).toFixed(4)}）`);
  fs.unlinkSync(f); for (const x of [f + '.out', f + '.err']) if (fs.existsSync(x)) fs.unlinkSync(x);
}

await go('orth_n40', 40, 3, 3, 2, 'orth');
await go('comp_n40', 40, 3, 3, 2, 'comp');
await go('comp_n15', 15, 4, 3, 1, 'comp');

