n0 = s


def sub(old, new, tag):
    global s
    assert s.count(old) == 1, f'锚点 [{tag}] 命中 {s.count(old)} 次'
    s = s.replace(old, new, 1)
    print(f'  ✓ {tag}')


# 1) 引入引擎调用
