    '注意事项')

# 4) computed：口径回显取自引擎
sub("""  computed: {
    importSheets() {
      return PM_IMPORT_SHEETS;
    },""",
    """  computed: {
    // 口径回显取自 R 的结果（它自己把 fdr 归一为 bh）—— 视图不另推一套，
    // 否则引擎改了口径定义而这里还写着旧话，界面就开始说谎。
    posthocPrimaryLabel() {
      const r = this.posthocResult;
      if (!r) return 'BH (FDR)';
      return r.primary === 'bonferroni' ? 'Bonferroni'
        : r.primary === 'none' ? '未校正（原始置换 p）' : 'BH (FDR)';
    },
    importSheets() {
      return PM_IMPORT_SHEETS;
