/**
 * 环境自检（doctor）：把"能不能跑"变成一条命令的确定答案。
 *
 * 为什么需要它：本项目有 22 个测试套件 + 4 个 R 尺子，任何一套在缺依赖时报的都是
 * "找不到 vite / 找不到 Rscript / 包版本不符"，用户分不清是代码坏了还是环境没装配。
 * 这里只回答一个问题：**现在这台机器缺什么，下一步该敲哪条命令。**
 *
 * 用法：node r-scripts/tools/check_env.mjs   （或 npm run verify:env）
 * 退出码：0 全部就绪；1 有缺失（不猜、不静默降级）
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const isWin = process.platform === 'win32';

const problems = [];
const notes = [];
const ok = (label, cond, detail = '', fix = '') => {
  if (cond) {
    console.log(`  \u2713 ${label}${detail ? `  (${detail})` : ''}`);
  } else {
    problems.push(`${label}${fix ? ` —— 下一步：${fix}` : ''}`);
    console.log(`  \u2717 ${label}${detail ? `  (${detail})` : ''}${fix ? `\n      下一步：${fix}` : ''}`);
  }
};

console.log('=== 1. Node 与包管理器 ===');
const nodeMajor = Number(process.versions.node.split('.')[0]);
ok(`Node >= 18（当前 ${process.versions.node}）`, nodeMajor >= 18,
  '', '装一个 Node 18+ 后重跑 npm run verify:env');
const npmVer = (() => {
  try { return execFileSync('npm', ['--version'], { encoding: 'utf8' }).trim(); } catch { return ''; }
})();
ok(`npm 可用${npmVer ? `（${npmVer}）` : ''}`, !!npmVer, '', '把 npm 加进 PATH');

console.log('\n=== 2. JS 依赖（根目录与 frontend）===');
const needRoot = ['electron', 'electron-egg'];
const rootNM = path.join(ROOT, 'node_modules');
ok('根目录 node_modules 存在', fs.existsSync(rootNM), '', 'npm install');
for (const p of needRoot) {
  if (!fs.existsSync(path.join(rootNM, p))) notes.push(`根依赖 ${p} 未安装`);
}
const feNM = path.join(ROOT, 'frontend', 'node_modules');
ok('frontend/node_modules 存在', fs.existsSync(feNM), '', 'npm run setup:frontend（或 npm --prefix frontend install）');
for (const p of ['vue', 'vite', 'element-plus', 'xlsx', 'file-saver']) {
  ok(`frontend 依赖 ${p}`, fs.existsSync(path.join(feNM, p)),
    '', 'npm --prefix frontend install');
}

console.log('\n=== 3. R 运行时 ===');
const rscript = path.join(ROOT, 'r-portable', 'bin', isWin ? 'Rscript.exe' : 'Rscript');
let lock = null;
try { lock = JSON.parse(fs.readFileSync(path.join(ROOT, 'r-runtime.lock.json'), 'utf8')); }
catch (e) { problems.push(`读不到 r-runtime.lock.json：${e.message}`); }

ok('r-portable/bin/Rscript 存在', fs.existsSync(rscript), rscript,
  isWin
    ? 'npm run setup:r（走 scripts/setup-r-runtime.ps1 装配运行时）'
    : '本项目当前只给 Windows 装配脚本；mac/linux 需自备 R 并放到 r-portable/');

let rVersion = '';
if (fs.existsSync(rscript)) {
  try {
    rVersion = execFileSync(rscript, ['--version'], { encoding: 'utf8' }).split('\n')[0];
  } catch (e) { rVersion = ''; }
  ok(`Rscript 能执行（${rVersion.trim().slice(0, 40)}）`, !!rVersion, '', '运行时可能损坏：npm run setup:r 重新装配');
}

console.log('\n=== 4. R 包是否满足 lockfile ===');
if (lock && fs.existsSync(rscript)) {
  const minReq = (lock.r && lock.r.min_required) || '4.3.0';
  const m = /(\d+)\.(\d+)/.exec(rVersion);
  const cur = m ? Number(m[1]) * 100 + Number(m[2]) : 0;
  const [a, b] = minReq.split('.').map(Number);
  ok(`R 版本 >= ${minReq}`, cur >= a * 100 + b, rVersion.trim(), '换更高版本的 R 运行时');

  // 一次调用问完所有必需包（逐个起进程要 20 多秒）
  const mods = Object.keys(lock.required || {});
  const js = `
    L <- jsonlite::fromJSON("${(path.join(ROOT, 'r-runtime.lock.json')).replace(/\\\\/g, '/')}")
    need <- unique(unlist(lapply(L$required, function(x) x$packages)))
    ip <- tryCatch(rownames(installed.packages()), error = function(e) character(0))
    miss <- setdiff(need, ip)
    ver <- sapply(need, function(p) if (p %in% ip) as.character(packageVersion(p)) else NA_character_)
    cat(jsonlite::toJSON(list(missing = miss, versions = ver), auto_unbox = TRUE))`;
  let info = null;
  try {
    const out = execFileSync(rscript, ['-e', js], { encoding: 'utf8', timeout: 120000 });
    info = JSON.parse(out.trim().split('\n').pop());
  } catch (e) {
    ok('向 R 询问包状态', false, String(e.message).slice(0, 120), 'npm run setup:r 之后重跑');
  }
  if (info) {
    const miss = info.missing || [];
    ok(`${mods.length} 个模块共 ${Object.keys(info.versions || {}).length} 个必需包全部就位`,
      miss.length === 0, miss.length ? `缺：${miss.join(', ')}` : '',
      isWin
        ? 'powershell -NoProfile -ExecutionPolicy Bypass -File scripts/setup-r-runtime.ps1 -Mode fromRepos'
        : '用你的 R 执行 install.packages(c("' + miss.join('","') + '"))');
    for (const mod of mods) {
      const pk = (lock.required[mod] && lock.required[mod].packages) || [];
      const bad = pk.filter((p) => !info.versions || info.versions[p] == null || info.versions[p] === null);
      console.log(`  ${bad.length ? '\u2717' : '\u2713'} ${mod.padEnd(22)} ${pk.map((p) => `${p}@${(info.versions || {})[p] || '-'}`).join(' ')}`);
      if (bad.length) problems.push(`模块 ${mod} 缺包：${bad.join(', ')}`);
    }
  }
  if (lock.missing_required && lock.missing_required.length) {
    notes.push(`lockfile 导出时就有缺失：${lock.missing_required.join(', ')}（说明导出那台机器也不全）`);
  }
}

console.log('\n=== 5. 装配来源是否可执行 ===');
if (lock) {
  const rel = lock.release || {};
  const hasUrl = !!rel.url;
  ok(`Release 附件地址已填（${rel.asset || '未命名'}）`, hasUrl,
    hasUrl ? rel.url : 'url / sha256 仍是 null',
    hasUrl ? '' : '上传运行时到 GitHub Release 后，把 tag/url/sha256/size_bytes 写回 r-runtime.lock.json；' +
      '或先用 -Mode fromRepos（从 CRAN/Bioconductor 现装）/ -Mode fromLocal -From <本机备份>');
  ok('校验和已声明（下载后能验真伪）', !!rel.sha256, rel.sha256 ? rel.sha256.slice(0, 16) + '…' : 'sha256 为空',
    hasUrl && !rel.sha256 ? '补 release.sha256，否则装配脚本只能跳过完整性检查' : '');
  ok('装配脚本在位', fs.existsSync(path.join(ROOT, 'scripts', 'setup-r-runtime.ps1')), '', '脚本丢失：从版本历史恢复');
  ok('R 侧校验器在位', fs.existsSync(path.join(ROOT, 'r-scripts/tools/verify_r_runtime.R')), '', '同上');
}

console.log('\n──────── 自检汇总 ────────');
if (notes.length) { console.log('提示：'); notes.forEach((n) => console.log('  · ' + n)); }
if (problems.length) {
  console.log(`\n[环境未就绪] ${problems.length} 项：`);
  problems.forEach((p) => console.log('  - ' + p));
  process.exit(1);
}
console.log('\n[PASS] 环境就绪：npm run dev 可以直接起，npm run verify 可以跑全部测试');

/**
 * 一键跑完全部验收：22 个 node 套件 + 4 个 R 尺子，给一张表和一个退出码。
 *
 * 为什么不用 shell 循环：Windows 的 cmd / PowerShell 与 bash 的 glob、引号规则都不一样，
 * 而这套测试是交付前的最后一道门 —— 它必须能在任何一台开发机上敲同一条命令。
 *
 * 用法：
 *   node r-scripts/tools/run_all_tests.mjs            # node 套件 + R 尺子
 *   node r-scripts/tools/run_all_tests.mjs --node     # 只跑 node（快，不起 R 分析）
 *   node r-scripts/tools/run_all_tests.mjs --r        # 只跑 R 尺子
 *   node r-scripts/tools/run_all_tests.mjs --only era # 名字含 era 的都跑
 *   node r-scripts/tools/run_all_tests.mjs --strict   # 把 stderr 也打出来（排错用）
 *
 * 退出码：0 全过；1 有套件失败
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const TOOLS = path.join(ROOT, 'r-scripts', 'tools');
const args = process.argv.slice(2);
const onlyNode = args.includes('--node');
const onlyR = args.includes('--r');
const strict = args.includes('--strict');
const iOnly = args.indexOf('--only');
const filter = iOnly >= 0 ? String(args[iOnly + 1] || '').toLowerCase() : '';

const isWin = process.platform === 'win32';
const RSCRIPT = process.env.RSCRIPT ||
  path.join(ROOT, 'r-portable', 'bin', isWin ? 'Rscript.exe' : 'Rscript');

const files = fs.readdirSync(TOOLS).sort();
const nodeSuites = files.filter((f) => /^(test|verify)_[a-z0-9_]+\.mjs$/.test(f));
const rSuites = files.filter((f) => /^verify_[a-z0-9_]+\.R$/.test(f));

const summary = [];
let bad = 0;

/** 从输出里抓「N 通过 / M 失败」或「[PASS] N 项全过」，抓不到就当失败（不许空过） */
function parseResult(out) {
  const failLine = /(\d+) 通过 \/ (\d+) 失败/.exec(out);
  if (failLine) return { pass: Number(failLine[1]), fail: Number(failLine[2]), parsed: true };
  const passLine = /\[PASS\] (\d+) 项全过/.exec(out);
  if (passLine) return { pass: Number(passLine[1]), fail: 0, parsed: true };
  const rfail = /\[FAIL\] (\d+) 项通过 \/ (\d+) 失败/.exec(out);
  if (rfail) return { pass: Number(rfail[1]), fail: Number(rfail[2]), parsed: true };
  if (/全部通过/.test(out)) return { pass: null, fail: 0, parsed: true };
  if (/所有模板统计量一致/.test(out)) return { pass: null, fail: 0, parsed: true };
  return { pass: null, fail: null, parsed: false };
}

function run(kind, name, cmd, cargs, opts = {}) {
  const t0 = Date.now();
  let r;
  try {
    r = spawnSync(cmd, cargs, { cwd: ROOT, encoding: 'utf8', timeout: opts.timeout || 2400000, maxBuffer: 64 * 1024 * 1024 });
  } catch (e) {
    summary.push({ kind, name, state: 'CRASH', detail: String(e.message).slice(0, 90), secs: 0 });
    bad++;
    return;
  }
  const out = `${r.stdout || ''}\n${r.stderr || ''}`;
  const parsed = parseResult(out);
  const secs = ((Date.now() - t0) / 1000).toFixed(1);
  let state, detail;
  if (r.error) { state = 'CRASH'; detail = String(r.error.message).slice(0, 90); }
  else if (!parsed.parsed) {
    // 没抓到汇总行 = 这套测试自己没报告结果。当成失败处理，不许"静默通过"。
    state = 'NO-SUMMARY';
    detail = (out.trim().split('\n').pop() || '无输出').slice(0, 90);
  } else if (parsed.fail) { state = 'FAIL'; detail = `${parsed.pass} 通过 / ${parsed.fail} 失败`; }
  else { state = 'PASS'; detail = parsed.pass == null ? 'ok' : `${parsed.pass} 项`; }
  if (r.status !== 0 && state === 'PASS') { state = 'FAIL'; detail = `退出码 ${r.status}（与汇总不一致）`; }
  if (state !== 'PASS') {
    bad++;
    if (strict) console.log(out.split('\n').slice(-40).join('\n'));
  }
  summary.push({ kind, name, state, detail, secs });
  console.log(`  ${state === 'PASS' ? '\u2713' : '\u2717'} ${name.padEnd(34)} ${state.padEnd(11)} ${String(detail).padEnd(26)} ${secs}s`);
}

const wantNode = !onlyR;
const wantR = !onlyNode;

if (wantNode) {
  console.log('\n=== node 套件（视图渲染 / spec 对账 / 运行时链路）===');
  for (const f of nodeSuites) {
    if (filter && !f.toLowerCase().includes(filter)) continue;
    run('node', f, process.execPath, [path.join(TOOLS, f)]);
  }
}
if (wantR) {
  console.log('\n=== R 尺子（统计口径的已知答案）===');
  if (!fs.existsSync(RSCRIPT)) {
    console.log(`  \u2717 Rscript 不存在：${RSCRIPT}`);
    console.log('    下一步：npm run setup:r（或 node r-scripts/tools/check_env.mjs 看缺什么）');
    bad++;
  } else {
    for (const f of rSuites) {
      if (filter && !f.toLowerCase().includes(filter)) continue;
      run('r', f, RSCRIPT, [path.join('r-scripts', 'tools', f)], { timeout: 2400000 });
    }
  }
}

console.log('\n──────── 汇总 ────────');
const by = {};
for (const s of summary) by[s.state] = (by[s.state] || 0) + 1;
console.log('  ' + Object.entries(by).map(([k, v]) => `${k}=${v}`).join('  '));
if (bad) {
  console.log('\n  失败/异常项：');
  summary.filter((s) => s.state !== 'PASS')
    .forEach((s) => console.log(`    - [${s.kind}] ${s.name}: ${s.state} ${s.detail}`));
  console.log('\n[FAIL] 有套件未通过');
  process.exit(1);
}
console.log(`\n[PASS] ${summary.length} 个套件全部通过`);

