arguments.content:
/**
 * GUI 端到端（真 Electron + CDP）
 *
 * 为什么非得是"真界面"：今天两个 bug 都藏在 GUI 层 ——
 *   (a) methods 里两个 confirmExport，后者静默覆盖前者，导出的 JSON 从来没走 spec；
 *   (b) build-w 不含前端构建，把几周前的脚手架 bundle 打进了安装包。
 * 两者在源码级断言里都是绿的（代码写得对 ✓ 配置也写了 ✓），只有"真的点开一次"才会露馅。
 *
 * 实现选择：这台机器没有外网，装不了 Playwright/Puppeteer；但仓库里有
 *   - node_modules/electron/dist/electron.exe（39.8.10）
 *   - node_modules/ws（8.21.3）
 * 所以直接用 CDP：启动真应用 -> 连 webSocketDebuggerUrl -> Runtime.evaluate 驱动真实 DOM。
 * 零新增依赖。
 *
 * 用法：node r-scripts/tools/test_e2e_gui.mjs [--headed] [--keep]
 *   默认 headless（offscreen 窗口）+ 用完即关；--keep 保留进程便于人工看。
 */
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const require_ = createRequire(path.join(ROOT, 'package.json'));
const WebSocket = require_('ws');

const isWin = process.platform === 'win32';
const ELECTRON = path.join(ROOT, 'node_modules', 'electron', 'dist', isWin ? 'electron.exe' : 'electron');
const PORT = Number(process.env.E2E_PORT || 9333);
const HEADED = process.argv.includes('--headed');
const KEEP = process.argv.includes('--keep');
const TIMEOUT = Number(process.env.E2E_TIMEOUT_MS || 180000);

let pass = 0; const fails = [];
const check = (name, cond, detail = '') => {
  if (cond) { pass++; console.log('  \u2713 ' + name); }
  else { fails.push(name + (detail ? ` —— ${detail}` : '')); console.log('  \u2717 ' + name + (detail ? `  [${String(detail).slice(0, 200)}]` : '')); }
};

if (!fs.existsSync(ELECTRON)) {
  console.log('[SKIP] 没有本地 electron 可执行文件：' + ELECTRON);
  console.log('RESULT pass=0 fail=0');
  process.exit(0);
}

// 独立 userData：electron/config 里 singleLock=true，若与桌面上正在跑的实例共用
// 用户目录，第二个进程会直接退出，表现为"e2e 起不来"这种假故障。
const profile = fs.mkdtempSync(path.join(os.tmpdir(), 'e2e-profile-'));
const dlDir = path.join(profile, 'downloads');
fs.mkdirSync(dlDir, { recursive: true });

console.log('\n=== 1. 启动真应用 ===');
const child = spawn(ELECTRON, [
  '.',
  `--remote-debugging-port=${PORT}`,
  `--user-data-dir=${profile}`,
  HEADED ? '' : '--window-size=1280,900'
].filter(Boolean), { cwd: ROOT, stdio: ['ignore', 'pipe', 'pipe'] });

let stdout = '';
child.stdout.on('data', (d) => { stdout += d.toString(); });
child.stderr.on('data', (d) => { stdout += d.toString(); });
child.on('exit', (code) => { console.log(`  (electron 退出，code=${code})`); });

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function waitForTarget(ms) {
  const end = Date.now() + ms;
  while (Date.now() < end) {
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json/list`);
      const list = await res.json();
      const page = list.find((t) => t.type === 'page' && t.webSocketDebuggerUrl);
      if (page) return page;
    } catch { /* CDP 还没起来 */ }
    if (child.killed || child.exitCode !== null) return null;
    await sleep(500);
  }
  return null;
}

const target = await waitForTarget(60000);
check('CDP 能连上应用页面（真进程 + 真渲染进程）', !!target,
  target ? '' : '没拿到 page target；启动日志尾部：' + stdout.slice(-300));

let ws = null;
let msgId = 0;
const pending = new Map();
const send = (method, params = {}) => new Promise((resolve, reject) => {
  const id = ++msgId;
  pending.set(id, { resolve, reject });
  ws.send(JSON.stringify({ id, method, params }));
});
// 页面上的 console.error 会被转成断言线索：不看它的话，Vue 报错只会表现为"元素不存在"
const pageErrors = [];
const consoleErrors = [];

function evalJs(expression, awaitPromise = false) {
  return send('Runtime.evaluate', {
    expression, returnByValue: true, awaitPromise
  }).then((r) => {
    if (r.exceptionDetails) {
      pageErrors.push(r.exceptionDetails.exception?.description || r.exceptionDetails.text);
      return { ok: false, value: null, err: r.exceptionDetails.exception?.description || 'eval threw' };
    }
    return { ok: true, value: r.result?.value };
  });
}

if (target) {
  ws = new WebSocket(target.webSocketDebuggerUrl, { perMessageDeflate: false });
  await new Promise((res, rej) => { ws.once('open', res); ws.once('error', rej); });
  ws.on('message', (raw) => {
    const m = JSON.parse(raw.toString());
    if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result); }
    if (m.method === 'Runtime.exceptionThrown') {
      pageErrors.push(m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text);
    }
    if (m.method === 'Log.entryAdded' && m.params.entry.level === 'error') {
      consoleErrors.push(m.params.entry.text);
    }
  });
  await send('Runtime.enable');
  await send('Log.enable').catch(() => {});
  // 把下载落到我们的临时目录，才能断言"点导出真的产生了文件"
  await send('Page.setDownloadBehavior', { behavior: 'allow', downloadPath: dlDir }).catch(() => {});

  console.log('\n=== 2. 首页（真 DOM，不是 jsdom 近似）===');
  const t = await evalJs('document.title');
  check('窗口标题是纯产品名（署名不进标题栏）', String(t.value).trim() === '\u7edf\u8ba1\u5206\u6790\u5e73\u53f0', JSON.stringify(t.value));
  const cards = await evalJs('document.querySelectorAll(".method-card, .card-item").length');
  check('\u9996\u9875\u6e32\u67d3\u51fa\u65b9\u6cd5\u5361\u7247', Number(cards.value) >= 5, 'cards=' + cards.value);
  const note = await evalJs('Array.from(document.querySelectorAll(".app-design-note")).map(e=>e.textContent).join("|")');
  check('\u7f72\u540d\u5728\u754c\u9762\u4e0a\u771f\u7684\u770b\u5f97\u89c1\uff08\u4e0d\u53ea\u662f\u5199\u5728源码里\uff09',
    String(note.value || '').includes('design for'), JSON.stringify(note.value));
  const bodyHasOld = await evalJs('document.body.innerText.includes("ElectronEgg") || document.body.innerText.includes("Hello World")');
  check('\u4e0d\u662f\u8001\u811a\u624b\u67b6\u9875\u9762\uff08\u4eca\u5929\u6253\u8fdb\u5b89\u88c5\u5305\u7684\u5c31\u662f\u5b83\uff09',
    bodyHasOld.value === false, String(bodyHasOld.value));
  check('\u9996\u9875\u6ca1\u6709 JS \u62a5\u9519', pageErrors.length === 0, pageErrors.join(' ; ').slice(0, 200));

  console.log('\n=== 3. \u771f\u70b9\u51fb\uff1a\u8def\u7531 -> \u6a21\u677f -> \u8fd0\u884c -> \u5bfc\u51fa ===');
  // hash 路由，直接改 location 比找卡片稳（卡片文案会变，路由名是 API）
  await evalJs('location.hash = "#/r-analysis/permanova"; "ok"');
  let ok = false; let snap = '';
  const deadline = Date.now() + TIMEOUT;
  while (Date.now() < deadline) {
    const r = await evalJs('!!document.querySelector("textarea") && document.body.innerText.length');
    if (r.value && Number(r.value) > 200) { ok = true; snap = String(r.value); break; }
    await sleep(500);
  }
  check('PERMANOVA \u9875\u771f\u6b63\u6e32\u67d3\u51fa\u6765\uff08\u6709\u8f93\u5165\u6846\u4e0e\u5185\u5bb9\uff09', ok, 'len=' + snap);

  if (ok) {
    const tpl = await evalJs(
      'JSON.stringify(Array.from(document.querySelectorAll("button")).map(b=>b.innerText.trim()).filter(Boolean).slice(0,40))'
    );
