    check('xlsx \u4e5f\u4e00\u8d77\u843d\u5730\uff08\u9ed8\u8ba4\u52fe\u9009\u91cc\u6709\u8868\u683c\uff09', xl.length >= 1, xl.join(','));
  } else {
