So implement `exportAllCharts()`:
```js
async exportAllCharts() {
  const echarts = await import('echarts');
  const { saveAs } = await import('file-saver');
  const types = this.chartTypes || [];
  const prev = this.activeChartType;
  const done = [];
  for (const t of types) {
    this.activeChartType = t.key ?? t.name;      // 触发 watch/渲染
    this.handleChartTypeChange?.();               // 若渲染靠事件而非 watch，手动调一次
    await this.$nextTick();
    await new Promise(r => setTimeout(r, 260));   // echarts 动画落定
    const el = this.$refs.pcoaChart;
    const chart = el && echarts.getInstanceByDom(el);
    if (!chart) continue;
    const url = chart.getDataURL({ type: 'png', pixelRatio: 2, backgroundColor: '#ffffff' });
    const bytes = Uint8Array.from(atob(url.split(',')[1]), c => c.charCodeAt(0));
    saveAs(new Blob([bytes], { type: 'image/png' }), `分析图表_${t.label}_${this.stamp()}.png`);
    done.push(t.label);
  }
  // 恢复用户原来看的那张：导出完不该把界面留在最后一张
  this.activeChartType = prev;
  this.handleChartTypeChange?.();
  if (!done.length) throw new Error('没有任何图表实例可导出（先运行分析）');
  return done;
}
